float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}
float noise(vec2 p) {
  vec2 i = floor(p), f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x),
    mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x),
    f.y
  );
}
float fbm(vec2 p) {
  float v = 0.0, a = 0.5;
  for (int i = 0; i < 4; i++) {
    v += a * noise(p);
    p = p * 2.04 + vec2(1.7, 9.2);
    a *= 0.5;
  }
  return v;
}
void main() {
  vec2 uv = v_uv;
  vec2 p = vec2(uv.x * (u_resolution.x / max(u_resolution.y, 1.0)), uv.y);
  float t = u_time * (0.38 + u_high * 0.22 + u_max * 0.35);

  // 鼠标附近产生热流扰动
  float md = length((uv - u_pointer) * vec2(u_resolution.x / max(u_resolution.y, 1.0), 1.0));
  float ripple = exp(-md * 3.8) * 0.32;

  float q = fbm(p * 1.6 + vec2(-t * 0.7, t * 0.25));
  float f = fbm(p * 2.2 + vec2(q * 2.1 - t * 0.45, q * 1.4 + ripple));

  // 用主题深色 -> 主色 -> 莫奈辅色 -> 白炽高光映射流体能量
  vec3 col = mix(u_accent_deep * 0.45, u_accent, smoothstep(0.18, 0.58, f));
  col = mix(col, u_monet_sec, smoothstep(0.45, 0.76, f + u_high * 0.14));
  float vein = smoothstep(0.64 - u_max * 0.12, 0.88, f + ripple);
  col = mix(col, mix(u_accent_light, vec3(1.0, 0.97, 0.90), 0.65), vein);

  // Max 档爆发扫光
  col += u_accent_light * u_burst * 0.35 * smoothstep(0.2, 1.0, uv.x);
  gl_FragColor = vec4(col, 0.96);
}
